do $validate$ declare s uuid;c integer;base_c integer;bad integer; begin select id into s from public.biblical_sources where slug='stepbible-lexical-pilot'; select count(*) into c from public.biblical_word_occurrences where source_id=s and enabled and review_status='approved' and ((book_code='PSA' and chapter=23 and verse=1) or (book_code='JHN' and chapter=3 and verse=16)); select count(*) into base_c from public.biblical_word_occurrences where source_id=s and enabled and review_status='approved' and textual_status='base' and ((book_code='PSA' and chapter=23 and verse=1) or (book_code='JHN' and chapter=3 and verse=16)); select count(*) into bad from public.biblical_word_occurrences where source_id=s and enabled and (content_hash is null or content_hash !~ '^[0-9a-f]{64}$'); if c<>31 then raise exception 'Se esperaban 31 ocurrencias; se obtuvieron %',c; end if; if base_c<>30 then raise exception 'Se esperaban 30 unidades base; se obtuvieron %',base_c; end if; if bad<>0 then raise exception 'Hashes de ocurrencias inválidos: %',bad; end if; end $validate$;